import std.io

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let t = true
    let nt = !t
    if nt == false { io.println("not-ok") } else { io.println("not-bad") }
    let x = 5
    let nx = -x
    if nx == 0 - 5 { io.println("neg-ok") } else { io.println("neg-bad") }
    let bx = ~x
    if bx == 0 - 6 { io.println("bnot-ok") } else { io.println("bnot-bad") }
    let z = 0
    let nz = -z
    if nz == 0 { io.println("negz-ok") } else { io.println("negz-bad") }
    return Ok(())
}
